<script lang="ts">
 import {TYPES} from '../domain/core.mjs';
 import {ART,ART_NAMES,cardArtKey} from '../ui/art.mjs';
 import {asset} from '../config/assets';
 import {onMount} from 'svelte';
 import {taskName} from '../ui/task-view.mjs';
 let form=$state<HTMLFormElement>();
 let draft=$state({type:'scene',text:'',note:'',minutes:5,cost:0,artKey:'auto'});
 let artKey=$derived(cardArtKey({id:'custom-preview',...draft}));
 let art=$derived(ART[artKey as keyof typeof ART]);
 function sync(){if(!form)return;const fields=new FormData(form);draft={type:String(fields.get('type')||'scene'),text:String(fields.get('text')||'').trim(),note:String(fields.get('note')||'').trim(),minutes:Number(fields.get('minutes')),cost:Number(fields.get('cost')),artKey:String(fields.get('artKey')||'auto')};}
 onMount(()=>queueMicrotask(sync));
</script>
<form id="card-form" class="panel card-editor" bind:this={form} oninput={sync} onchange={sync}>
 <header><p class="eyebrow">我们的原创委托 / CREATE A QUEST</p><h2>写一张自己的卡</h2><p class="help">选一幅画，把想一起做的事写下来。</p></header>
 <div class="editor-workbench"><div class="editor-basics">
 <div class="field-row"><div><label for="card-type">类型</label><select name="type" id="card-type">{#each Object.keys(TYPES) as key}<option value={key}>{taskName(key)}</option>{/each}</select></div><div><label for="card-place">适合哪里</label><select name="place" id="card-place"><option value="both">室内外都可以</option><option value="indoor">以室内为主</option><option value="outdoor">以户外为主</option></select></div></div>
 <label for="card-text">任务内容</label><textarea id="card-text" name="text" maxlength="200" required placeholder="例如：各找一处像笑脸的城市细节，给对方看"></textarea>
 </div>
 <fieldset class="art-picker"><legend>给这张卡选一幅画</legend><label class="art-auto"><input type="radio" name="artKey" value="auto" checked><span><strong>自动匹配</strong><small>按任务内容选择插画</small></span></label><div class="art-options">{#each Object.entries(ART) as [key,art]}<label class="art-option"><input type="radio" name="artKey" value={key} aria-label={ART_NAMES[key as keyof typeof ART_NAMES]}><img src={asset(art.src)} alt="" width="120" height="160" loading="lazy"><span>{ART_NAMES[key as keyof typeof ART_NAMES]}</span></label>{/each}</div><p class="help">选定后，收藏册和抽到的任务卡都会使用这幅画。</p></fieldset>
 <aside class="editor-preview" aria-label="卡片预览"><p class="eyebrow">成牌预览 / YOUR QUEST</p><article class={`draft-card ${draft.type}`} data-card-preview><div class="draft-heading">{taskName(draft.type)}</div><img src={asset(art.src)} alt={art.alt} width="600" height="800" draggable="false"><div class="draft-copy"><h3>{draft.text||'把想一起做的小事，写成下一张委托。'}</h3>{#if draft.note}<p class="draft-note">{draft.note}</p>{/if}<p class="draft-meta"><span>约 {Number.isFinite(draft.minutes)&&draft.minutes>0?draft.minutes:5} 分钟</span><span>{Number.isFinite(draft.cost)&&draft.cost>0?`预算 ¥${draft.cost} 内`:'无需花费'}</span></p></div></article><p class="preview-caption" data-preview-art>{draft.artKey==='auto'?'自动匹配':'已选插画'} · {ART_NAMES[artKey as keyof typeof ART_NAMES]}</p></aside>
 <div class="editor-extras">
 <label for="card-note">小提示（可不填）</label><input id="card-note" name="note" maxlength="500" placeholder="可以留一个线索，或者写下完成方式">
 <div class="field-row"><div><label for="card-minutes">预计分钟</label><input id="card-minutes" name="minutes" type="number" value="5" min="1" max="120" required></div><div><label for="card-cost">费用上限（元）</label><input id="card-cost" name="cost" type="number" value="0" min="0" max="10000" step="0.01" inputmode="decimal" required></div></div><p class="help">上限为0时，这张卡可以在零消费模式出现。随心探索会抽到你们写的卡。</p><div class="spacer"></div><button class="btn block" type="submit">放进收藏册</button>
 </div></div>
</form>
<style>
 .card-editor header{padding-bottom:16px;border-bottom:1px dashed var(--line)}.card-editor header h2{margin:0}.card-editor header .eyebrow{margin-bottom:6px}
 .editor-workbench{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:20px 28px;align-items:start}.editor-basics,.editor-extras,.art-picker{grid-column:1;min-width:0}.editor-preview{grid-column:2;grid-row:1/span 3;position:sticky;top:24px;min-width:0;margin-top:18px}.editor-preview>.eyebrow{text-align:center;font-size:9px;margin-bottom:10px}.draft-card{border:4px solid #19394f;background:#fff6df;box-shadow:3px 4px #17354d22;border-radius:5px;overflow:hidden;--draft-tone:var(--green)}.draft-card.talk{--draft-tone:var(--blue)}.draft-card.event{--draft-tone:var(--rust)}.draft-heading{padding:8px 10px;font-size:.8125rem;font-weight:700;color:var(--draft-tone);border-bottom:1px solid var(--line)}.draft-card>img{display:block;width:100%;height:auto;aspect-ratio:3/4;object-fit:cover;image-rendering:pixelated}.draft-copy{padding:12px;border-top:2px solid #cdb879;min-width:0}.draft-copy h3{font-size:.9375rem;line-height:1.5;overflow-wrap:anywhere;white-space:pre-wrap;margin:0}.draft-note{font-size:.75rem;line-height:1.6;overflow-wrap:anywhere;white-space:pre-wrap;color:var(--muted);margin:8px 0 0}.draft-meta{display:flex;flex-wrap:wrap;gap:4px 10px;font-size:.6875rem;color:var(--muted);padding-top:8px;border-top:1px solid var(--line);margin:12px 0 0}.preview-caption{font-size:.75rem;color:var(--green);text-align:center;margin:10px 0 0}
 .art-picker{margin:0;border:0;padding:0;min-width:0}.art-picker legend{font-weight:650;font-size:.9375rem;margin-bottom:10px}.art-auto{display:flex;gap:10px;align-items:center;padding:12px;border:1px solid var(--line);margin:0 0 12px}.art-auto input,.art-option input{width:18px;height:18px;accent-color:var(--green);padding:0}.art-auto small{display:block;font-weight:400;color:var(--muted);font-size:.75rem}.art-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.art-option{position:relative;margin:0;padding:5px;border:2px solid var(--line);background:var(--paper);border-radius:4px;cursor:pointer}.art-option img{display:block;width:100%;height:auto;aspect-ratio:3/4;object-fit:cover;image-rendering:pixelated}.art-option input{position:absolute;right:8px;top:8px;margin:0;background:var(--white)}.art-option span{display:block;font-size:.75rem;text-align:center;padding:7px 0 3px}.art-option:has(input:checked),.art-auto:has(input:checked){border-color:var(--green);background:#e7f0e7;box-shadow:2px 2px var(--green)}.art-option:focus-within{outline:2px solid var(--accent);outline-offset:3px}
 @media(max-width:800px){.editor-workbench{grid-template-columns:minmax(0,1fr);gap:20px}.editor-preview{grid-column:1;grid-row:auto;position:static;margin-top:0}.art-options{gap:8px}.art-option span{font-size:.6875rem}.card-editor{padding:16px}.draft-card{display:grid;grid-template-columns:100px minmax(0,1fr)}.draft-heading{grid-column:1/-1}.draft-card>img{height:100%;min-height:134px;max-height:220px;grid-column:1;object-position:center}.draft-copy{grid-column:2;border-top:0;border-left:1px solid #cdb879;padding:10px}.draft-copy h3{font-size:.875rem}.draft-meta{margin-top:8px}.draft-note{font-size:.6875rem}}
</style>
